  skullBash: Object.freeze({ en: "The user tucks in its head to raise its Defense stat on the first turn, then rams the target on the next turn.", es: "El usuario se prepara y sube su Defensa en el primer turno y en el segundo arremete con un cabezazo.", fr: "Le lanceur baisse la tête pour augmenter sa Défense au premier tour et percuter l’ennemi au second.", de: "Der Anwender erhöht in Runde 1 seine Verteidigung und greift in Runde 2 an.", ja: "１ターン目に 頭を ひっこめて 防御を あげる。 ２ターン目に 相手を 攻撃する。", zh: "第１回合把头缩进去， 从而提高防御。 第２回合攻击对手。" }),
  skyAttack: Object.freeze({ en: "A second-turn attack move where critical hits land more easily. This may also make the target flinch.", es: "Ataca durante dos turnos y suele asestar un golpe crítico. También puede amedrentar al objetivo.", fr: "Une attaque en deux tours au taux de critiques élevé. Peut aussi apeurer l’ennemi.", de: "Anwender greift in der zweiten Runde mit hoher Volltrefferquote an. Ziel schreckt eventuell zurück.", ja: "２ターン目に 相手を 攻撃する。 たまに ひるませる。 急所にも 当たりやすい。", zh: "第２回合攻击对手。 偶尔使对手畏缩。 也容易击中要害。" }),
  skyUppercut: Object.freeze({ en: "This move can’t be used. It’s recommended that this move is forgotten. Once forgotten, this move can’t be remembered.", es: "Este movimiento no se puede usar, por lo que sería mejor olvidarlo, aunque eso implique que no se pueda recordar posteriormente.", fr: "Cette capacité ne peut pas être utilisée. Il est recommandé de l’oublier, même s’il sera impossible de se la remémorer une fois oubliée.", de: "Diese Attacke kann nicht eingesetzt werden. Du solltest dein Pokémon sie vergessen lassen. Beachte aber, dass es sich danach nicht wieder an sie erinnern kann.", ja: "この技は 使えません 思い出すことが できなくなりますが 技を 忘れることを おすすめします", zh: "无法使用这个招式。 虽然忘记之后就再也想不起来了， 但还是建议忘记这个招式。" }),
  slackOff: Object.freeze({ en: "The user slacks off, restoring its own HP by up to half of its max HP.", es: "El usuario se relaja y restaura la mitad de sus PS máximos.", fr: "Le lanceur se tourne les pouces et récupère jusqu’à la moitié de ses PV max.", de: "Durch Müßiggang werden KP des Anwenders um 50 % der maximalen KP aufgefüllt.", ja: "怠けて やすむ。 自分の ＨＰを 最大ＨＰの 半分 回復する。", zh: "偷懒休息。 回复自己最大ＨＰ的一半。" }),
  slam: Object.freeze({ en: "The target is slammed with a long tail, vines, or the like to inflict damage.", es: "Golpea con la cola o con lianas, por ejemplo, para causar daño al objetivo.", fr: "Fouette l’ennemi avec la queue ou une liane, par exemple, pour infliger des dégâts.", de: "Schlag mit einem langen Schweif, einer Ranke oder Ähnlichem.", ja: "長い しっぽや つるなどを 使い 相手を たたきつけて 攻撃する。", zh: "使用长长的尾巴或藤蔓等 摔打对手进行攻击。" }),
  slash: Object.freeze({ en: "The target is attacked with a slash of claws or blades. Critical hits land more easily.", es: "Ataca con cuchillas o con pinzas. Suele asestar un golpe crítico.", fr: "Un coup de griffe ou autre tranche l’ennemi. Taux de critiques élevé.", de: "Hieb mit Klauen oder Ähnlichem. Hohe Volltrefferquote.", ja: "ツメや カマなどで 相手を 切り裂いて 攻撃する。 急所に 当たりやすい。", zh: "用爪子或镰刀等 劈开对手进行攻击。 容易击中要害。" }),
  sleepPowder: Object.freeze({ en: "The user scatters a big cloud of sleep-inducing dust around the target.", es: "Esparce polvo que duerme al objetivo.", fr: "Le lanceur répand une poudre soporifique qui endort la cible.", de: "Verstreut Schlafpuder, der das Ziel eventuell in Schlaf versetzt.", ja: "眠くなる 粉を たくさん ふりまいて 相手を 眠り状態に する。", zh: "撒出催眠粉， 从而让对手陷入睡眠状态。" }),
  sleepTalk: Object.freeze({ en: "While it is asleep, the user randomly uses one of the moves it knows.", es: "Mientras duerme, usa uno de sus movimientos elegido al azar.", fr: "Le lanceur utilise une de ses capacités au hasard pendant qu’il dort.", de: "Anwender setzt per Zufall eine ihm bekannte Attacke ein. Klappt nur, wenn der Anwender gerade schläft.", ja: "自分が おぼえている 技の うち どれか １つを くりだす。 自分が 寝ているときだけ 使える。", zh: "从自己已学会的招式中 任意使出１个。 只能在自己睡觉时使用。" }),
